    /// <summary>What the encounter leaves behind when it dies.</summary>
    private static readonly PatternBranch[][] OnDieVariants = BuildOnDieVariants();

    private static PatternBranch[][] BuildOnDieVariants()
    {
        PatternBranch[][] variants = new PatternBranch[367][];
        OnDieVariants0(variants);
        OnDieVariants1(variants);
        OnDieVariants2(variants);
        OnDieVariants3(variants);
        return variants;
    }

